#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int x, y, z;
} Triple;

int cmp(const void *a, const void *b) {
    Triple *t1 = (Triple *)a;
    Triple *t2 = (Triple *)b;
    if (t1->x != t2->x) return t1->x - t2->x;
    if (t1->y != t2->y) return t1->y - t2->y;
    return t1->z - t2->z;
}

int cmp_y(const void *a, const void *b) {
    Triple *t1 = (Triple *)a;
    Triple *t2 = (Triple *)b;
    if (t1->y != t2->y) return t1->y - t2->y;
    return t1->z - t2->z;
}

int max(int a, int b) {
    return a > b ? a : b;
}

int main() {
    int n, a, b;
    while (scanf("%d %d %d", &n, &a, &b) == 3) {
        if (n == 0 && a == 0 && b == 0) break;

        int m = n + (a > 0 ? 1 : 0);
        Triple *triples = (Triple *)malloc(m * sizeof(Triple));

        for (int i = 0; i < n; i++) {
            scanf("%d %d %d", &triples[i].x, &triples[i].y, &triples[i].z);
        }

        if (a > 0) {
            triples[n].x = a;
            triples[n].y = b;
            triples[n].z = 0;
        }

        // Sort by x first
        qsort(triples, m, sizeof(Triple), cmp);

        // DP using BIT over y-coordinate after coordinate compression
        // First compress y values
        int *ys = (int *)malloc(m * sizeof(int));
        for (int i = 0; i < m; i++) {
            ys[i] = triples[i].y;
        }
        qsort(ys, m, sizeof(int), cmp_y);
        int unique_y = 0;
        for (int i = 0; i < m; i++) {
            if (i == 0 || ys[i] != ys[i-1]) {
                ys[unique_y++] = ys[i];
            }
        }

        // BIT for max
        int *bit = (int *)calloc(unique_y + 2, sizeof(int));

        int ans = 0;
        // Process in order of x, and for equal x, process larger y first to avoid using same x
        // We'll process groups of same x together
        int i = 0;
        while (i < m) {
            int j = i;
            while (j < m && triples[j].x == triples[i].x) j++;

            // For this group, compute dp values using BIT from previous groups
            int *dp_vals = (int *)malloc((j - i) * sizeof(int));
            for (int k = i; k < j; k++) {
                int y_idx = -1;
                // binary search for y index (strictly less)
                int lo = 0, hi = unique_y - 1;
                while (lo <= hi) {
                    int mid = (lo + hi) / 2;
                    if (ys[mid] < triples[k].y) {
                        y_idx = mid;
                        lo = mid + 1;
                    } else {
                        hi = mid - 1;
                    }
                }

                int best = 0;
                if (y_idx >= 0) {
                    // query BIT up to y_idx
                    int idx = y_idx + 1;
                    while (idx > 0) {
                        best = max(best, bit[idx]);
                        idx -= idx & -idx;
                    }
                }
                dp_vals[k - i] = best + 1;
            }

            // Now update BIT with these dp values (only for z=0 if applicable)
            for (int k = i; k < j; k++) {
                if (triples[k].z == 0 && a > 0) continue; // skip the generated one for update
                int y_idx = -1;
                int lo = 0, hi = unique_y - 1;
                while (lo <= hi) {
                    int mid = (lo + hi) / 2;
                    if (ys[mid] == triples[k].y) {
                        y_idx = mid;
                        break;
                    } else if (ys[mid] < triples[k].y) {
                        lo = mid + 1;
                    } else {
                        hi = mid - 1;
                    }
                }
                if (y_idx >= 0) {
                    int idx = y_idx + 1;
                    int val = dp_vals[k - i];
                    while (idx <= unique_y) {
                        bit[idx] = max(bit[idx], val);
                        idx += idx & -idx;
                    }
                }
            }

            // Update answer with dp values
            for (int k = i; k < j; k++) {
                ans = max(ans, dp_vals[k - i]);
            }

            free(dp_vals);
            i = j;
        }

        printf("%d\n", ans);

        free(triples);
        free(ys);
        free(bit);
    }
    return 0;
}

