    const Triple *q = (const Triple *)b;
    if (p->x != q->x) return (p->x < q->x) ? -1 : 1;
    if (p->y != q->y) return (p->y < q->y) ? -1 : 1;
    if (p->z != q->z) return (p->z < q->z) ? -1 : 1;
    return 0;
}

