struct BIT2D {
    int n;
    vector<vector<pair<int,int>>> bit; // each BIT node stores (z, value) sorted by z
    vector<vector<int>> tree; // actual BIT over compressed z

    BIT2D(int n) : n(n), bit(n + 1), tree(n + 1) {}

    void addPoint(int y, int z, int val) {
        for (int i = y; i <= n; i += i & -i) {
            bit[i].push_back({z, val});
        }
    }

    void build() {
        for (int i = 1; i <= n; i++) {
            sort(bit[i].begin(), bit[i].end());
            bit[i].erase(unique(bit[i].begin(), bit[i].end(),
                [](auto &a, auto &b) { return a.first == b.first; }), bit[i].end());
            tree[i].assign(bit[i].size() + 1, 0);
        }
    }

    void update(int y, int z, int val) {
        for (int i = y; i <= n; i += i & -i) {
            int idx = lower_bound(bit[i].begin(), bit[i].end(), make_pair(z, 0)) - bit[i].begin() + 1;
            int m = tree[i].size();
            while (idx < m) {
                tree[i][idx] = max(tree[i][idx], val);
                idx += idx & -idx;
            }
        }
    }

    int query(int y, int z) {
        int res = 0;
        for (int i = y; i > 0; i -= i & -i) {
            int idx = upper_bound(bit[i].begin(), bit[i].end(), make_pair(z-1, INT_MAX)) - bit[i].begin();
            while (idx > 0) {
                res = max(res, tree[i][idx]);
                idx -= idx & -idx;
            }
        }
        return res;
    }
};

