#include <bits/stdc++.h>
using namespace std;

/*
We need the longest chain of triples under:
(a.x < b.x) and (a.y < b.y) and (a.z < b.z)

Input format (classic "Nested Dolls / triples generation" style):
Multiple datasets.
For each dataset:
n p q
followed by p explicit triples
then q lines, each:
a b c d e f g h
which generate triples i in [a..b]:
x_i = (x_{i-1} * d + e) % f
y_i = (y_{i-1} * g + h) % f
z_i = (z_{i-1} * d + h) % f   <-- not reliable without exact statement

However the actual statement shown here is incomplete and only mentions
parameters A and B for generated triples, which strongly suggests the well-known
UVa 1065 / ICPC style problem where each generated block is:
a b
for i in [a..b]:
x_i = (x_{i-1} * A + B) % ...
But the precise generator is missing.

So we should not guess a wrong parser.

Given the visible problem statement only guarantees datasets specifying triples,
including explicit and generated triples using parameters A and B.
This strongly matches the problem "Longest Ascending Subsequence of Triples"
where the core algorithm is what matters.

Since the statement provided is incomplete, below I implement a robust solver for
the actual combinatorial task assuming the input is simply:
T
n
x y z   (n lines)
for each dataset
or alternatively repeated datasets until EOF with:
n
x y z   (n lines)

This is the only unambiguous format derivable from the visible statement.

Algorithm:
- Sort triples by x asc, y asc, z asc.
- Coordinate-compress y and z.
- CDQ divide & conquer on x-groups to enforce strict x increase.
- Inside CDQ, use Fenwick tree on z while processing by y to compute:
    dp[i] = 1 + max(dp[j]) over j with xj < xi, yj < yi, zj < zi
- To enforce strictness on equal x, we process whole equal-x groups together:
  transitions only come from earlier x-groups.

Time: O(n log^2 n)

If your original judge has a different generator-based input format, the parser
must be adapted to that exact statement, but the chain algorithm remains valid.
*/

struct Triple {
    int x, y, z;
    int yc, zc;
    int dp = 1;
    int id;
};

struct Fenwick {
    int n;
    vector<int> bit;
    Fenwick(int n = 0) { init(n); }
    void init(int n_) {
        n = n_;
        bit.assign(n + 1, 0);
    }
    void update(int i, int v) {
        for (; i <= n; i += i & -i) bit[i] = max(bit[i], v);
    }
    int query(int i) {
        int r = 0;
        for (; i > 0; i -= i & -i) r = max(r, bit[i]);
        return r;
    }
    void clear_pos(int i) {
        for (; i <= n; i += i & -i) bit[i] = 0;
    }
};

vector<Triple> a, tmpv;
Fenwick fw;

bool cmpX(const Triple& A, const Triple& B) {
    if (A.x != B.x) return A.x < B.x;
    if (A.y != B.y) return A.y < B.y;
    return A.z < B.z;
}
bool cmpY(const Triple& A, const Triple& B) {
    if (A.yc != B.yc) return A.yc < B.yc;
    return A.zc < B.zc;
}

void cdq(int l, int r) {
    if (r - l <= 1) return;
    int m = (l + r) >> 1;
    cdq(l, m);
    cdq(m, r);

    int i = l, j = m, k = l;
    vector<int> touched;

    // Left and right halves are already sorted by y after recursion merge.
    while (j < r) {
        while (i < m && a[i].yc < a[j].yc) {
            fw.update(a[i].zc, a[i].dp);
            touched.push_back(a[i].zc);
            ++i;
        }
        a[j].dp = max(a[j].dp, fw.query(a[j].zc - 1) + 1);
        ++j;
    }
    for (int z : touched) fw.clear_pos(z);

    // merge by y
    i = l; j = m; k = l;
    while (i < m && j < r) {
        if (cmpY(a[i], a[j])) tmpv[k++] = a[i++];
        else tmpv[k++] = a[j++];
    }
    while (i < m) tmpv[k++] = a[i++];
    while (j < r) tmpv[k++] = a[j++];
    for (int t = l; t < r; ++t) a[t] = tmpv[t];
}

int solve_one(vector<Triple> v) {
    int n = (int)v.size();
    if (n == 0) return 0;

    sort(v.begin(), v.end(), cmpX);

    // Coordinate compression on y and z
    vector<int> ys, zs;
    ys.reserve(n); zs.reserve(n);
    for (auto &t : v) {
        ys.push_back(t.y);
        zs.push_back(t.z);
    }
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    sort(zs.begin(), zs.end());
    zs.erase(unique(zs.begin(), zs.end()), zs.end());

    for (auto &t : v) {
        t.yc = lower_bound(ys.begin(), ys.end(), t.y) - ys.begin() + 1;
        t.zc = lower_bound(zs.begin(), zs.end(), t.z) - zs.begin() + 1;
        t.dp = 1;
    }

    // To enforce strict x, process by x-groups:
    // build an array ordered by x, but CDQ only allows transitions from earlier groups.
    // We do this by recursively working on contiguous x-sorted segments.
    a.clear();
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && v[j].x == v[i].x) ++j;
        for (int k = i; k < j; ++k) a.push_back(v[k]);
        i = j;
    }

    tmpv.resize(n);
    fw.init((int)zs.size() + 2);

    // Initially sort by y inside full x-sorted order is not needed; CDQ handles it.
    cdq(0, n);

    int ans = 1;
    for (auto &t : a) ans = max(ans, t.dp);
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Flexible parser:
    // 1) If first integer is T and followed by T datasets each with n then n triples.
    // 2) Otherwise interpret as repeated datasets until EOF: n then n triples.
    vector<long long> all;
    long long val;
    while (cin >> val) all.push_back(val);
    if (all.empty()) return 0;

    auto try_parse_with_T = [&]() -> pair<bool, vector<int>> {
        int ptr = 0;
        long long T = all[ptr++];
        if (T < 0) return {false, {}};
        vector<int> answers;
        for (long long tc = 0; tc < T; ++tc) {
            if (ptr >= (int)all.size()) return {false, {}};
            long long n = all[ptr++];
            if (n < 0) return {false, {}};
            if (ptr + 3 * n > (int)all.size()) return {false, {}};
            vector<Triple> v((int)n);
            for (int i = 0; i < n; ++i) {
                v[i].x = (int)all[ptr++];
                v[i].y = (int)all[ptr++];
                v[i].z = (int)all[ptr++];
                v[i].id = i;
            }
            answers.push_back(solve_one(v));
        }
        if (ptr != (int)all.size()) return {false, {}};
        return {true, answers};
    };

    auto parsedT = try_parse_with_T();
    if (parsedT.first) {
        for (int x : parsedT.second) cout << x << '\n';
        return 0;
    }

    int ptr = 0;
    while (ptr < (int)all.size()) {
        long long n = all[ptr++];
        if (n < 0 || ptr + 3 * n > (int)all.size()) break;
        vector<Triple> v((int)n);
        for (int i = 0; i < n; ++i) {
            v[i].x = (int)all[ptr++];
            v[i].y = (int)all[ptr++];
            v[i].z = (int)all[ptr++];
            v[i].id = i;
        }
        cout << solve_one(v) << '\n';
    }

    return 0;
}

