public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNext()) {
            int n = sc.nextInt();
            int a = sc.nextInt();
            int b = sc.nextInt();
            if (n == 0 && a == 0 && b == 0) break;

            long[] x = new long[n];
            long[] y = new long[n];
            long[] z = new long[n];

            for (int i = 0; i < n; i++) {
                x[i] = sc.nextLong();
                y[i] = sc.nextLong();
                z[i] = sc.nextLong();
            }

            // generate remaining triples
            int m = n;
            n = n * (n - 1) / 2;
            long[] X = new long[n];
            long[] Y = new long[n];
            long[] Z = new long[n];

            int idx = 0;
            for (int i = 0; i < m; i++) {
                for (int j = i + 1; j < m; j++) {
                    X[idx] = x[i] * x[j] + y[i] * y[j] + z[i] * z[j];
                    Y[idx] = x[i] * y[j] + y[i] * z[j] + z[i] * x[j];
                    Z[idx] = x[i] * z[j] + y[i] * x[j] + z[i] * y[j];
                    idx++;
                }
            }

            // combine into list of triples
            List<Triple> list = new ArrayList<>();
            for (int i = 0; i < m; i++) {
                list.add(new Triple(x[i], y[i], z[i]));
            }
            for (int i = 0; i < n; i++) {
                list.add(new Triple(X[i], Y[i], Z[i]));
            }

            // coordinate compress y and z
            TreeSet<Long> ySet = new TreeSet<>();
            TreeSet<Long> zSet = new TreeSet<>();
            for (Triple t : list) {
                ySet.add(t.y);
                zSet.add(t.z);
            }
            List<Long> yList = new ArrayList<>(ySet);
            List<Long> zList = new ArrayList<>(zSet);

            for (Triple t : list) {
                t.yIdx = Collections.binarySearch(yList, t.y) + 1;
                t.zIdx = Collections.binarySearch(zList, t.z) + 1;
            }

            // sort by x, then y, then z (all ascending)
            Collections.sort(list, (t1, t2) -> {
                if (t1.x != t2.x) return Long.compare(t1.x, t2.x);
                if (t1.y != t2.y) return Long.compare(t1.y, t2.y);
                return Long.compare(t1.z, t2.z);
            });

            int total = list.size();
            int maxY = yList.size() + 1;
            int maxZ = zList.size() + 1;

            // 2D BIT
            int[][] bit = new int[maxY + 1][maxZ + 1];
            int ans = 0;

            for (Triple t : list) {
                int best = query(bit, t.yIdx - 1, t.zIdx - 1) + 1;
                ans = Math.max(ans, best);
                update(bit, t.yIdx, t.zIdx, best);
            }

            System.out.println(ans);
        }
        sc.close();
    }

    static void update(int[][] bit, int y, int z, int val) {
        for (int i = y; i < bit.length; i += i & -i) {
            for (int j = z; j < bit[0].length; j += j & -j) {
                bit[i][j] = Math.max(bit[i][j], val);
            }
        }
    }

    static int query(int[][] bit, int y, int z) {
        int res = 0;
        for (int i = y; i > 0; i -= i & -i) {
            for (int j = z; j > 0; j -= j & -j) {
                res = Math.max(res, bit[i][j]);
            }
        }
        return res;
    }

    static class Triple {
        long x, y, z;
        int yIdx, zIdx;
        Triple(long x, long y, long z) {
            this.x = x;
            this.y = y;
            this.z = z;
        }
    }
}

