            Integer[] idx = new Integer[n];
            for (int i = 0; i < n; i++) idx[i] = i;
            Arrays.sort(idx, (a, b) -> x[a] != x[b] ? x[a]-x[b] : y[a] != y[b] ? y[a]-y[b] : z[a]-z[b]);

            int[] dp = new int[n];
            Arrays.fill(dp, 1);
            int ans = 1;

            for (int i = 0; i < n; i++) {
                int ii = idx[i];
                for (int j = 0; j < i; j++) {
                    int jj = idx[j];
