import java.io.*;
import java.util.*;

/*
  Longest ascending series of triples under:
    (xa < xb) and (ya < yb) and (za < zb)

  Input format (multiple datasets, until EOF):
    n m
    x1 y1 z1
    ...
    xm ym zm
    A B

  Total triples = n.
  First m triples are given explicitly.
  Remaining n-m triples are generated by:
    t[i] = ( (A*x_prev + B) % MOD, (A*y_prev + B) % MOD, (A*z_prev + B) % MOD )
  where prev is the previous triple and MOD = 2^31.

  Output:
    For each dataset, print the length of the longest ascending series.

  Approach:
    This is a 3D LIS / maximum chain in a partial order.

    Steps:
    1) Generate all triples.
    2) Sort by x, then y, then z.
    3) Process equal-x groups together so transitions only come from strictly smaller x.
    4) Inside each x-group, compute dp using only points with smaller y and smaller z.
       This is done with CDQ divide-and-conquer on y and a Fenwick tree on z.
       Equal-y values are also grouped to preserve strict y.
    5) After finishing one x-group, insert its points into the global Fenwick tree
       so later x-groups can extend from them.

    Complexity: O(n log^2 n)
*/

public class Main {
    static final long MOD = 1L << 31;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        Long nextLongNullable() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return nextLongNullable().intValue();
        }

        long nextLong() throws IOException {
            return nextLongNullable();
        }
    }

    static class Triple {
        long x, y, z;
        int zi;     // compressed z
        int dp = 1; // longest chain ending here
    }

    static class Fenwick {
        int n;
        int[] bit;

        Fenwick(int n) {
            this.n = n;
            this.bit = new int[n + 2];
        }

        void update(int idx, int val) {
            for (int i = idx; i <= n; i += i & -i) {
                if (bit[i] < val) bit[i] = val;
            }
        }

        int query(int idx) {
            int res = 0;
            for (int i = idx; i > 0; i -= i & -i) {
                if (res < bit[i]) res = bit[i];
            }
            return res;
        }

        void clearIndices(int[] used, int usedCnt) {
            for (int i = 0; i < usedCnt; i++) {
                int idx = used[i];
                for (int j = idx; j <= n; j += j & -j) bit[j] = 0;
            }
        }
    }

    static Triple[] arr;
    static Fenwick localBIT;
    static int[] touched;
    static int touchedCnt;

    static void touchUpdate(int idx, int val) {
        int i = idx;
        while (i <= localBIT.n) {
            if (localBIT.bit[i] == 0) touched[touchedCnt++] = i;
            if (localBIT.bit[i] < val) localBIT.bit[i] = val;
            i += i & -i;
        }
    }

    static int touchQuery(int idx) {
        int res = 0;
        for (int i = idx; i > 0; i -= i & -i) {
            if (res < localBIT.bit[i]) res = localBIT.bit[i];
        }
        return res;
    }

    static Triple[] temp;

    // CDQ on [l, r), arr sorted by y then z
    static void cdq(int l, int r) {
        if (r - l <= 1) return;
        int m = (l + r) >>> 1;
        cdq(l, m);
        cdq(m, r);

        int i = l, j = m, k = l;

        // Merge by y, but for equal y process right queries before left updates
        // to enforce strict y (<), not <=.
        while (i < m && j < r) {
            if (arr[i].y < arr[j].y) {
                touchUpdate(arr[i].zi, arr[i].dp);
                temp[k++] = arr[i++];
            } else {
                int best = touchQuery(arr[j].zi - 1);
                if (arr[j].dp < best + 1) arr[j].dp = best + 1;
                temp[k++] = arr[j++];
            }
        }
        while (j < r) {
            int best = touchQuery(arr[j].zi - 1);
            if (arr[j].dp < best + 1) arr[j].dp = best + 1;
            temp[k++] = arr[j++];
        }
        while (i < m) {
            touchUpdate(arr[i].zi, arr[i].dp);
            temp[k++] = arr[i++];
        }

        for (int p = l; p < r; p++) arr[p] = temp[p];
        localBIT.clearIndices(touched, touchedCnt);
        touchedCnt = 0;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            Long nObj = fs.nextLongNullable();
            if (nObj == null) break;
            int n = nObj.intValue();
            int m = fs.nextInt();

            Triple[] pts = new Triple[n];
            for (int i = 0; i < m; i++) {
                Triple t = new Triple();
                t.x = fs.nextLong();
                t.y = fs.nextLong();
                t.z = fs.nextLong();
                pts[i] = t;
            }

            long A = fs.nextLong();
            long B = fs.nextLong();

            for (int i = m; i < n; i++) {
                Triple prev = pts[i - 1];
                Triple t = new Triple();
                t.x = (A * prev.x + B) % MOD;
                t.y = (A * prev.y + B) % MOD;
                t.z = (A * prev.z + B) % MOD;
                pts[i] = t;
            }

            // Coordinate compression for z
            long[] zs = new long[n];
            for (int i = 0; i < n; i++) zs[i] = pts[i].z;
            Arrays.sort(zs);
            int zc = 0;
            for (int i = 0; i < n; i++) {
                if (i == 0 || zs[i] != zs[i - 1]) zs[zc++] = zs[i];
            }
            for (int i = 0; i < n; i++) {
                pts[i].zi = lowerBound(zs, zc, pts[i].z) + 1;
            }

            // Sort by x, then y, then z
            Arrays.sort(pts, (a, b) -> {
                if (a.x != b.x) return Long.compare(a.x, b.x);
                if (a.y != b.y) return Long.compare(a.y, b.y);
                return Long.compare(a.z, b.z);
            });

            Fenwick globalBIT = new Fenwick(zc);
            localBIT = new Fenwick(zc);
            touched = new int[(zc + 5) * 20 / 10 + 100];
            temp = new Triple[n];

            int ans = 0;

            int s = 0;
            while (s < n) {
                int e = s;
                while (e < n && pts[e].x == pts[s].x) e++;

                // Base from smaller x only
                for (int i = s; i < e; ) {
                    int j = i;
                    while (j < e && pts[j].y == pts[i].y) j++;

                    // same x and same y cannot connect; query all first
                    for (int k = i; k < j; k++) {
                        int best = globalBIT.query(pts[k].zi - 1);
                        pts[k].dp = Math.max(pts[k].dp, best + 1);
                    }
                    i = j;
                }

                // Now handle transitions inside same x-group? No, x must be strictly increasing,
                // so no transitions within same x-group are allowed at all.
                // Therefore we only insert this group after all queries are done.

                for (int i = s; i < e; i++) {
                    globalBIT.update(pts[i].zi, pts[i].dp);
                    if (ans < pts[i].dp) ans = pts[i].dp;
                }

                s = e;
            }

            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }

    static int lowerBound(long[] a, int n, long x) {
        int l = 0, r = n;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (a[m] < x) l = m + 1;
            else r = m;
        }
        return l;
    }
}
